#include <fstream>
#include <iostream>
#include <unistd.h> // for sleep()

using namespace std;

// Helper function to write a value to a sysfs file
void writeToFile(const string& path, const string& value) {
    ofstream fs(path);
    if (!fs.is_open()) {
        cerr << "Failed to open " << path << endl;
        return;
    }
    fs << value;
    fs.close();
}

int main() {
    // Export GPIO pins (change numbers as per your wiring)
    writeToFile("/sys/class/gpio/export", "17"); // Motor A IN1
    writeToFile("/sys/class/gpio/export", "18"); // Motor A IN2
    writeToFile("/sys/class/gpio/export", "27"); // Motor A ENA
    writeToFile("/sys/class/gpio/export", "22"); // Motor B IN1
    writeToFile("/sys/class/gpio/export", "23"); // Motor B IN2
    writeToFile("/sys/class/gpio/export", "24"); // Motor B ENB

    sleep(1); // Wait for sysfs to create the gpio folders

    // Set directions to output
    writeToFile("/sys/class/gpio/gpio17/direction", "out");
    writeToFile("/sys/class/gpio/gpio18/direction", "out");
    writeToFile("/sys/class/gpio/gpio27/direction", "out");
    writeToFile("/sys/class/gpio/gpio22/direction", "out");
    writeToFile("/sys/class/gpio/gpio23/direction", "out");
    writeToFile("/sys/class/gpio/gpio24/direction", "out");

    // Enable both motors (set ENA and ENB HIGH)
    writeToFile("/sys/class/gpio/gpio27/value", "1"); // Motor A enable
    writeToFile("/sys/class/gpio/gpio24/value", "1"); // Motor B enable

    // Set Motor A forward (IN1=1, IN2=0)
    writeToFile("/sys/class/gpio/gpio17/value", "1");
    writeToFile("/sys/class/gpio/gpio18/value", "0");

    // Set Motor B backward (IN1=0, IN2=1)
    writeToFile("/sys/class/gpio/gpio22/value", "0");
    writeToFile("/sys/class/gpio/gpio23/value", "1");

    sleep(5); // Let motors run for 5 seconds

    // Stop both motors (set IN1 and IN2 LOW)
    writeToFile("/sys/class/gpio/gpio17/value", "0");
    writeToFile("/sys/class/gpio/gpio18/value", "0");
    writeToFile("/sys/class/gpio/gpio22/value", "0");
    writeToFile("/sys/class/gpio/gpio23/value", "0");

    // Optionally, disable motors (set ENA and ENB LOW)
    writeToFile("/sys/class/gpio/gpio27/value", "0");
    writeToFile("/sys/class/gpio/gpio24/value", "0");

    return 0;
}
```

