  pinMode(RESTART_BUTTON_PIN, INPUT_PULLUP); // подтяжка к плюсу
  // ... остальной ваш setup
}

void restartGame() {
  ball_x = 64;
  ball_y = 16;
  ball_dir_x = 1;
  ball_dir_y = 1;
  cpu_y = 8;
  player_y = 8;
  display.clearDisplay();
  drawCourt();
  display.fillRect(ball_x, ball_y, BALL_SIZE, WHITE);
  display.drawFastVLine(CPU_X, cpu_y, PADDLE_HEIGHT, WHITE);
  display.drawFastVLine(PLAYER_X, player_y, PADDLE_HEIGHT, WHITE);
  display.display();
  ball_update = millis();
  paddle_update = millis();
}

void loop() {
  if (digitalRead(RESTART_BUTTON_PIN) == LOW) {
    restartGame();
    delay(300); // простая защита от дребезга и повторных срабатываний
  }
  // ... остальной ваш loop
}
