**My Answer:**

The main issue in your code is that you are storing `startMarker` as a `Transform` reference (`this.transform`). Since you move the object during the coroutine, `startMarker.position` changes as well, so your interpolation is always between the *current* position and `endPos`, not the *original* position and `endPos`. This causes the movement to not behave as expected.

**How to fix:**

1. **Store the start position and rotation as values, not references.**
   - Use `Vector3 startPos` and `Quaternion startRot` to store the starting position and rotation at the beginning of the move.

2. **Calculate `distance` before `journeyAmount`.**
   - You should update `distance` first, then calculate `journeyAmount = distance / journeyLength`.

3. **Coroutine management.**
   - When you call `StopCoroutine(move())`, it doesn't stop the running coroutine because `move()` creates a new enumerator each time. Instead, store the coroutine reference when you start it, and stop it using that reference.

**Revised code:**

```csharp
using System.Collections;
using UnityEngine;

public class moveCard : MonoBehaviour
{
    public storage Storage;
    public float speed = 20f;
    private float startTime;
    private float journeyLength;
    private Vector3 startPos;
    private Quaternion startRot;
    public int dir = 1;
    private Vector3 endPos;
    private Coroutine moveCoroutine;

    void Awake() {
        if (gameObject.name == "reference") {
            Storage.movePos = transform.position;
        }
    }

    public void moveToCenter() {
        startTime = Time.time;
        startPos = transform.position;
        startRot = transform.rotation;

        endPos = new Vector3(Storage.movePos.x * dir, Storage.movePos.y, Storage.movePos.z);
        journeyLength = Vector3.Distance(startPos, endPos);

        if (moveCoroutine != null) {
            StopCoroutine(moveCoroutine);
        }
        moveCoroutine = StartCoroutine(move());
        Invoke("stopAnimation", 2f);
    }

    IEnumerator move() {
        while (true) {
            float distance = (Time.time - startTime) * speed;
            float journeyAmount = distance / journeyLength;

            if (journeyAmount < 1f) {
                transform.position = Vector3.Lerp(startPos, endPos, journeyAmount);
                transform.rotation = Quaternion.Lerp(startRot, Quaternion.Euler(Storage.rot), journeyAmount);
                yield return null;
            } else {
                transform.position = endPos;
                transform.rotation = Quaternion.Euler(Storage.rot);
                yield break;
            }
        }
    }

    private void stopAnimation() {
        Debug.Log("coroutine ended");
        if (moveCoroutine != null) {
            StopCoroutine(moveCoroutine);
            moveCoroutine = null;
        }
    }
}
```

**Summary of fixes:**
