Below is a SwiftUI-based implementation for a basic "Tennis Score Tracker" app. This app allows users to track scores for up to three sets, input scores, and, when an advanced option is enabled, record details for each point (winner, unforced error, forced error, ace, return winner, serve winner).

```swift
import SwiftUI

enum PointDetail: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"
    var id: String { rawValue }
}

struct Point: Identifiable {
    let id = UUID()
    let player: Int // 1 or 2
    let detail: PointDetail?
    let timestamp: Date
}

struct Game {
    var p1Points: Int = 0
    var p2Points: Int = 0
}

struct SetScore {
    var p1Games: Int = 0
    var p2Games: Int = 0
}

class Match: ObservableObject {
    @Published var sets: [SetScore] = [SetScore(), SetScore(), SetScore()]
    @Published var currentSet: Int = 0
    @Published var currentGame = Game()
    @Published var points: [Point] = []

    func addPoint(player: Int, detail: PointDetail? = nil) {
        if player == 1 {
            currentGame.p1Points += 1
        } else {
            currentGame.p2Points += 1
        }
        points.append(Point(player: player, detail: detail, timestamp: Date()))
        checkGameOver()
    }

    func checkGameOver() {
        let p1 = currentGame.p1Points
        let p2 = currentGame.p2Points
        if (p1 >= 4 || p2 >= 4) && abs(p1 - p2) >= 2 {
            if p1 > p2 {
                sets[currentSet].p1Games += 1
            } else {
                sets[currentSet].p2Games += 1
            }
            currentGame = Game()
            checkSetOver()
        }
    }

    func checkSetOver() {
        let set = sets[currentSet]
        if (set.p1Games >= 6 || set.p2Games >= 6) && abs(set.p1Games - set.p2Games) >= 2 {
            if currentSet < 2 {
                currentSet += 1
            }
        }
    }

    func reset() {
        sets = [SetScore(), SetScore(), SetScore()]
        currentSet = 0
        currentGame = Game()
        points = []
    }
}

struct ContentView: View {
