            Text("Tennis Score Tracker").font(.largeTitle)
            Text("Set \(match.currentSet + 1) of 3")
            HStack {
                VStack {
                    Text("Player 1: \(match.sets[match.currentSet].p1Games)")
                    Button("Add Point") {
                        if advanced {
