                    }
                }
                VStack {
                    Text("Player 2: \(match.sets[match.currentSet].p2Games)")
                    Button("Add Point") {
                        if advanced {
                            match.addPoint(player: 2, detail: selectedDetailP2)
                        } else {
                            match.addPoint(player: 2)
                        }
                    }
                    if advanced {
                        Picker("Detail", selection: $selectedDetailP2) {
                            ForEach(PointDetail.allCases) { d in
