Here is a production-ready React Native component called `ExpandableText` that displays a single line of text with a "See more" link if the text overflows. When "See more" is clicked, the full text is shown. The component uses the `onTextLayout` event to determine if the text overflows and supports customization via props.

```jsx
import React, { useState } from 'react';
import { Text, View, StyleSheet } from 'react-native';
import PropTypes from 'prop-types';

const ExpandableText = ({
  text,
  numberOfLines = 1,
  seeMoreText = 'See more',
  seeLessText = 'See less',
  textStyle,
  seeMoreStyle,
  containerStyle,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showSeeMore, setShowSeeMore] = useState(false);

  const onTextLayout = (e) => {
    if (e.nativeEvent.lines.length > numberOfLines) {
      setShowSeeMore(true);
    }
  };

  return (
    <View style={containerStyle}>
      <Text
        style={textStyle}
        numberOfLines={isExpanded ? undefined : numberOfLines}
        onTextLayout={onTextLayout}
      >
        {text}
        {!isExpanded && showSeeMore && (
          <Text
            style={[styles.seeMore, seeMoreStyle]}
            onPress={() => setIsExpanded(true)}
          >
            {' '}{seeMoreText}
          </Text>
        )}
        {isExpanded && showSeeMore && (
          <Text
            style={[styles.seeMore, seeMoreStyle]}
            onPress={() => setIsExpanded(false)}
          >
            {' '}{seeLessText}
          </Text>
        )}
      </Text>
    </View>
  );
};

ExpandableText.propTypes = {
  text: PropTypes.string.isRequired,
  numberOfLines: PropTypes.number,
  seeMoreText: PropTypes.string,
  seeLessText: PropTypes.string,
  textStyle: PropTypes.object,
  seeMoreStyle: PropTypes.object,
  containerStyle: PropTypes.object,
