4. Check if the parsed value is exactly one of {0, 1, 2, 3, 10, 11, 42}.

Here is a sample implementation:

```cpp
#include <QCoreApplication>
#include <QDebug>
#include <QSet>
#include <QString>
#include <QVariant>
#include "xlsxdocument.h"

bool parseCellToInt(const QVariant &cellValue, int &result) {
    // If it's a number, check if it's an integer
    if (cellValue.canConvert<double>()) {
        double d = cellValue.toDouble();
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d, double(i))) {
            result = i;
            return true;
        }
    }
    // If it's a string, parse accordingly
    QString s = cellValue.toString().trimmed().toLower();
    if (s.isEmpty()) return false;

    bool ok = false;
    // Hexadecimal: 0x...
    if (s.startsWith("0x")) {
        result = s.mid(2).toInt(&ok, 16);
        return ok;
    }
    // Binary: 0b...
    if (s.startsWith("0b")) {
        result = s.mid(2).toInt(&ok, 2);
        return ok;
    }
    // Octal: starts with 0, more than one digit, all digits 0-7
    if (s.startsWith('0') && s.length() > 1 && s.indexOf(QRegularExpression("[^0-7]")) == -1) {
        result = s.toInt(&ok, 8);
        return ok;
    }
    // Decimal
    result = s.toInt(&ok, 10);
    if (ok) return true;
    // Try as double, but only accept if integer
    double d = s.toDouble(&ok);
    if (ok) {
        int i = static_cast<int>(d);
        if (qFuzzyCompare(d, double(i))) {
            result = i;
            return true;
