      let lines = code.split('\n').length;
      lineNums.innerHTML = Array.from({length:lines},(_,i)=>i+1).join('\n');
      // Status
      let pos = editor.selectionStart;
      let before = code.slice(0,pos);
      let ln = before.split('\n').length;
      let col = before.split('\n').pop().length+1;
