    document.getElementById('open').onclick = ()=>document.getElementById('filein').click();
    document.getElementById('filein').onchange = e=>{
      let f = e.target.files[0];
      if(!f) return;
      let r = new FileReader();
      r.onload = ev=>{
        editor.value = ev.target.result;
        pushUndo();
        updateAll();
      };
      r.readAsText(f);
    };
    function saveFile() {
      let blob = new Blob([editor.value],{type:'text/plain'});
      let a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'note.'+currentLang;
      a.click();
      URL.revokeObjectURL(a.href);
    }
    document.getElementById('save').onclick = saveFile;
    document.getElementById('undo').onclick = undo;
    document.getElementById('redo').onclick = redo;
    // --- Find/Replace ---
    function showFind() { findPanel.style.display='flex'; findInput.focus(); updateFind(); }
    function hideFind() { findPanel.style.display='none'; }
    findBtn.onclick = showFind;
    document.getElementById('closefind').onclick = hideFind;
    function updateFind() {
      let val = editor.value, q = findInput.value;
      findMatches = [];
      if(!q) { findIdx=-1; updateAll(); return; }
      let re;
      try {
        re = regexChk.checked ? new RegExp(q,'g') : new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g');
      } catch { return; }
      let m;
      while((m=re.exec(val))!==null) {
        findMatches.push([m.index, m[0].length]);
        if(m.index===re.lastIndex) re.lastIndex++;
      }
      findIdx = findMatches.length?0:-1;
      updateAll();
      selectFind();
    }
    function selectFind() {
      if(findIdx<0||!findMatches.length) return;
      let [start,len] = findMatches[findIdx];
      editor.focus();
      editor.setSelectionRange(start, start+len);
      let lines = editor.value.slice(0,start).split('\n').length;
      editor.scrollTop = (lines-1)*20;
    }
    document.getElementById('findnext').onclick = ()=>{
      if(!findMatches.length) return;
      findIdx = (findIdx+1)%findMatches.length;
      updateAll(); selectFind();
    };
    document.getElementById('findprev').onclick = ()=>{
      if(!findMatches.length) return;
      findIdx = (findIdx-1+findMatches.length)%findMatches.length;
      updateAll(); selectFind();
    };
    findInput.oninput = updateFind;
    regexChk.onchange = updateFind;
    document.getElementById('replaceone').onclick = ()=>{
      if(findIdx<0||!findMatches.length) return;
      let [start,len] = findMatches[findIdx];
      let val = editor.value;
      editor.value = val.slice(0,start)+replaceInput.value+val.slice(start+len);
      pushUndo();
      updateFind();
    };
    document.getElementById('replaceall').onclick = ()=>{
      let q = findInput.value;
      if(!q) return;
      let re;
      try {
        re = regexChk.checked ? new RegExp(q,'g') : new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g');
      } catch { return; }
      editor.value = editor.value.replace(re, replaceInput.value);
      pushUndo();
      updateFind();
    };
    // --- Load ---
    window.onload = ()=>{
      let saved = localStorage.getItem('advnp-content');
      if(saved) editor.value = saved;
      let l = localStorage.getItem('advnp-lang');
      if(l) { currentLang = l; langSel.value = l; }
      pushUndo();
      updateAll();
    };
  </script>
</body>
</html>
