#include <array>
#include <string>
#include <vector>
using namespace std;

struct Node {
    array<Node*, 26> node;
    int cnt;
    Node() : cnt(0) { node.fill(nullptr); }
};

class Trie {
public:
    Trie() { root = new Node(); }
    void insert(const string& s) {
        Node* cur = root;
        for (char c : s) {
            int idx = c - 'a';
