            cur = cur->node[idx];
            cur->cnt++;
        }
    }
    int queryPrefix(const string& s) {
        Node* cur = root;
        int sum = 0;
        for (char c : s) {
            int idx = c - 'a';
            if (!cur->node[idx]) break;
            cur = cur->node[idx];
            sum += cur->cnt;
        }
        return sum;
    }
private:
    Node* root;
};

class Solution {
public:
