**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: some edges (roads) already exist, and the cost to build a new road between two houses is the sum of their prices. The goal is to connect all houses (nodes) with the minimum total cost.

**Approach:**

1. **Model the problem:** Each house is a node. Some roads already exist (edges with zero cost). The cost to build a new road between house i and house j is a[i] + a[j].
2. **Find connected components:** Use Union-Find (DSU) to find all connected components after adding the existing roads.
3. **Connect components:** To connect all components with minimal cost, connect the cheapest house in each component to the globally cheapest house among all houses. This is because connecting two components via their cheapest houses minimizes the cost.
4. **Implementation:**
   - For each component, find its cheapest house.
   - Find the globally cheapest house.
   - For each component (except the one containing the globally cheapest house), add a road between its cheapest house and the globally cheapest house.

**C++ Code:**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x != y) parent[y] = x;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        dsu.unite(u, v);
    }

    // Find the cheapest house in each component
    vector<int> min_in_comp(n, -1);
    for (int i = 0; i < n; ++i) {
        int p = dsu.find(i);
        if (min_in_comp[p] == -1 || a[i] < a[min_in_comp[p]]) min_in_comp[p] = i;
    }

    // Find the globally cheapest house
    int global_min = min_in_comp[0];
    for (int i = 1; i < n; ++i) {
        if (min_in_comp[i] != -1 && a[min_in_comp[i]] < a[global_min]) global_min = min_in_comp[i];
    }

    // Connect all other components to the global_min
    vector<pair<int, int>> roads;
    int root = dsu.find(global_min);
    for (int i = 0; i < n; ++i) {
        if (min_in_comp[i] != -1 && dsu.find(i) != root) {
            roads.emplace_back(global_min + 1, min_in_comp[i] + 1);
            dsu.unite(global_min, min_in_comp[i]);
        }
    }

    cout << roads.size() << "\n";
    for (auto &r : roads) cout << r.first << " " << r.second << "\n";
    return 0;
}
```

**Explanation:**
- We use DSU to find components.
- For each component, we find its cheapest house.
- We connect all components to the component with the globally cheapest house.
- This ensures minimal total cost and full connectivity.

