**My Answer:**

**Problem Restatement:**
Given n houses, each with a price, and m existing roads, we need to add the minimum-cost set of new roads so that the city is fully connected (i.e., there is a path between any two houses). The cost of building a road between house i and house j is a[i] + a[j].

**Approach:**
1. Use Union-Find (Disjoint Set Union, DSU) to find the connected components of the current graph.
2. For each component, find the house with the minimum price.
3. To connect all components with minimal cost, connect the cheapest house in the entire city to the cheapest house in every other component (the "star" method).
4. Output the number of new roads and the list of roads.

**C++ Implementation:**
```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        dsu.unite(u, v);
    }

    // Find the minimum price house in each component
    vector<int> min_in_comp(n, -1);
    for (int i = 0; i < n; ++i) {
        int p = dsu.find(i);
        if (min_in_comp[p] == -1 || a[i] < a[min_in_comp[p]])
            min_in_comp[p] = i;
    }

    // Collect unique components and their min nodes
    vector<int> reps;
    for (int i = 0; i < n; ++i)
        if (min_in_comp[i] != -1)
            reps.push_back(min_in_comp[i]);

    if (reps.size() == 1) {
        cout << 0 << "\n";
        return 0;
    }

    // Find the global minimum node
    int min_node = reps[0];
    for (int x : reps)
        if (a[x] < a[min_node])
            min_node = x;

    // Connect min_node to all other reps
    vector<pair<int, int>> edges;
    for (int x : reps) {
        if (x == min_node) continue;
        edges.emplace_back(min_node + 1, x + 1);
    }

    cout << edges.size() << "\n";
    for (auto [u, v] : edges)
        cout << u << " " << v << "\n";
    return 0;
}
```

