**Prompt Recap:**  
Write code for a geometry shader in Unity that samples a texture with transparency, creates a quad for each pixel that is not transparent, and extrudes each quad by a factor.

---

**My Answer:**

To achieve this in Unity, you need a geometry shader that:

- Receives a mesh of points, each corresponding to a pixel in the texture (with matching UVs).
- Samples the texture at each point's UV.
- If the alpha is above a threshold, emits a quad (two triangles) at that position, extruded by a factor.

**Shader Code (HLSL/CG):**

```hlsl
Shader "Custom/ExtrudedTextureQuads"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrude ("Extrude Factor", Float) = 0.1
        _AlphaThreshold ("Alpha Threshold", Range(0,1)) = 0.1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #pragma target 4.0

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrude;
            float _AlphaThreshold;

            struct appdata
            {
                float3 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 vertex : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = UnityObjectToClipPos(float4(v.vertex, 1.0));
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> triStream)
            {
                float4 col = tex2D(_MainTex, IN[0].uv);
                if (col.a < _AlphaThreshold)
                    return;

                // Define quad size in clip space (for demo; for real use, compute in world/view space)
                float size = 0.02;

                float4 basePos = IN[0].vertex;

                float4 offsets[4] = {
                    float4(-size, -size, 0, 0),
                    float4( size, -size, 0, 0),
                    float4( size,  size, _Extrude, 0),
                    float4(-size,  size, _Extrude, 0)
                };

                g2f o[4];
                for (int i = 0; i < 4; ++i)
                {
                    o[i].vertex = basePos + offsets[i];
                    o[i].uv = IN[0].uv;
                }

                // Emit two triangles (quad)
                triStream.Append(o[0]);
                triStream.Append(o[1]);
                triStream.Append(o[2]);

                triStream.Append(o[2]);
                triStream.Append(o[3]);
                triStream.Append(o[0]);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return tex2D(_MainTex, i.uv);
            }
            ENDCG
        }
    }
    FallBack "Diffuse"
}
```

