    Vector2[] uvs = new Vector2[w * h];
    int[] indices = new int[w * h];

    for (int y = 0; y < h; ++y)
    {
        for (int x = 0; x < w; ++x)
        {
            int i = y * w + x;
            vertices[i] = new Vector3(x, y, 0);
            uvs[i] = new Vector2((float)x / w, (float)y / h);
            indices[i] = i;
        }
