            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = UnityObjectToClipPos(float4(v.vertex, 1.0));
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> triStream)
            {
                float4 col = tex2D(_MainTex, IN[0].uv);
                if (col.a < _AlphaThreshold)
                    return;

                // Calculate quad size in clip space (approximate)
                float pixelSize = 0.02; // You may want to adjust this

                float4 basePos = IN[0].vertex;

                // Four corners of the quad, extruded along z
                float4 bl = basePos + float4(-pixelSize, -pixelSize, 0, 0);
                float4 br = basePos + float4( pixelSize, -pixelSize, 0, 0);
                float4 tr = basePos + float4( pixelSize,  pixelSize, _Extrude, 0);
                float4 tl = basePos + float4(-pixelSize,  pixelSize, _Extrude, 0);

                g2f o;

                // First triangle
                o.vertex = bl; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = br; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = tr; o.uv = IN[0].uv; triStream.Append(o);

                // Second triangle
                o.vertex = tr; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = tl; o.uv = IN[0].uv; triStream.Append(o);
                o.vertex = bl; o.uv = IN[0].uv; triStream.Append(o);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                fixed4 col = tex2D(_MainTex, i.uv);
                clip(col.a - _AlphaThreshold);
                return col;
            }
            ENDCG
        }
    }
    FallBack "Diffuse"
}
```

