**9. Example Code Skeleton:**
```cpp
#include <Wire.h>
#include <RTClib.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define OLED_RESET -1
Adafruit_SSD1306 display(128, 64, &Wire, OLED_RESET);
RTC_DS3231 rtc;

const int livingRoomLightPin = 3;
const int livingRoomTvPin = 5;
const int bedroomLightPin = 6;
const int bedroomTvPin = 9;
const int nightModePin = 2;

float accelRatio = 6.0;
bool nightModeFull = true; // true=2hr, false=1hr

DateTime startOfDayReal;

void setup() {
  pinMode(livingRoomLightPin, OUTPUT);
  pinMode(livingRoomTvPin, OUTPUT);
  pinMode(bedroomLightPin, OUTPUT);
  pinMode(bedroomTvPin, OUTPUT);
  pinMode(nightModePin, INPUT_PULLUP);

  rtc.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();

  DateTime now = rtc.now();
  startOfDayReal = DateTime(now.year(), now.month(), now.day(), 0, 0, 0);
}

void loop() {
  DateTime now = rtc.now();
  TimeSpan elapsed = now - startOfDayReal;
  long simSeconds = (long)(elapsed.totalseconds() * accelRatio) % 86400;
  int hour = simSeconds / 3600;
  int minute = (simSeconds % 3600) / 60;
  int simMins = hour * 60 + minute;

  // Read night mode button
  if (digitalRead(nightModePin) == LOW) nightModeFull = !nightModeFull;

  // Event logic (example times)
  // Morning: 7:00–8:00
  if (simMins >= 420 && simMins < 480) {
    analogWrite(bedroomLightPin, 255);
    tvFlicker(bedroomTvPin);
    displayEvent(hour, minute, "Morning TV");
  }
  // Evening: 18:00–22:00
  else if (simMins >= 1080 && simMins < 1320) {
    analogWrite(livingRoomLightPin, 255);
    tvFlicker(livingRoomTvPin);
    displayEvent(hour, minute, "Evening TV");
  }
  // Night: 22:00–24:00 (or 23:00 if nightModeFull==false)
  else if (simMins >= 1320 && simMins < (nightModeFull ? 1440 : 1380)) {
    analogWrite(bedroomLightPin, 0);
    tvFlicker(bedroomTvPin);
    displayEvent(hour, minute, "Bedtime TV");
  }
  else {
    analogWrite(livingRoomLightPin, 0);
    analogWrite(livingRoomTvPin, 0);
    analogWrite(bedroomLightPin, 0);
    analogWrite(bedroomTvPin, 0);
    displayEvent(hour, minute, "Idle");
  }

  delay(100);
}

void tvFlicker(int pin) {
  analogWrite(pin, random(50, 200));
}

void displayEvent(int hour, int minute, const char* event) {
  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(0,0);
  display.printf("%02d:%02d\n", hour, minute);
  display.setTextSize(1);
  display.setCursor(0, 30);
  display.print(event);
  display.display();
}
```
