    const json = await res.json();
    return json.id;
  }

  async updatePermissions(userId: string, permissions: PermissionPayload): Promise<UserCredentials> {
    const res = await this.request.post('/users/v2/permissions', { data: { ...permissions, id: userId } });
    if (res.status() !== 200) throw new Error('Permission update failed');
    return await res.json();
  }

  async createUserWithPermissions(
    userPayload: CreateUserPayload,
    permissions: PermissionPayload
  ): Promise<UserCredentials> {
    const userId = await this.createUser(userPayload);
    return await this.updatePermissions(userId, permissions);
  }
}

