This is a classic problem of calculating the union area of axis-aligned rectangles, where rectangles may overlap. The standard efficient solution is to use a sweep line (scanning line) algorithm with a segment tree, and discretize the y-coordinates because the coordinate range is huge but the number of rectangles is small.

**Algorithm Steps:**
1. For each rectangle, create two events: one for the left edge (entering) and one for the right edge (leaving), each with the x-coordinate and the y-interval.
2. Collect all y1 and y2, sort and deduplicate them to discretize the y-axis.
3. Sort all events by x.
4. Use a segment tree to maintain the total covered length on the y-axis as the sweep line moves.
5. For each event, calculate the area covered since the last x, and update the segment tree for the current event's y-interval.
6. Output the result modulo 1e9+7.

**C++ Code:**
```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
const int MOD = 1e9+7;

struct Event {
    ll x;
    int y1, y2;
    int type;
    Event(ll x, int y1, int y2, int type): x(x), y1(y1), y2(y2), type(type) {}
    bool operator<(const Event& e) const { return x < e.x; }
};

struct SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len;
    vector<ll> ys;
    SegmentTree(const vector<ll>& ys): ys(ys) {
        n = ys.size() - 1;
        cnt.assign(4*n, 0);
        len.assign(4*n, 0);
    }
    void update(int idx, int l, int r, int ql, int qr, int val) {
        if (qr <= l || ql >= r) return;
        if (ql <= l && r <= qr) {
            cnt[idx] += val;
        } else {
            int m = (l + r) / 2;
            update(idx*2, l, m, ql, qr, val);
            update(idx*2+1, m, r, ql, qr, val);
        }
        if (cnt[idx] > 0) len[idx] = ys[r] - ys[l];
        else if (r - l == 1) len[idx] = 0;
        else len[idx] = len[idx*2] + len[idx*2+1];
    }
};

int main() {
    int n;
    cin >> n;
    vector<vector<ll>> rects(n, vector<ll>(4));
    vector<ll> ys;
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        cin >> rects[i][0] >> rects[i][1] >> rects[i][2] >> rects[i][3];
        ys.push_back(rects[i][1]);
        ys.push_back(rects[i][3]);
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    for (int i = 0; i < n; ++i) {
        int y1 = lower_bound(ys.begin(), ys.end(), rects[i][1]) - ys.begin();
        int y2 = lower_bound(ys.begin(), ys.end(), rects[i][3]) - ys.begin();
        events.emplace_back(rects[i][0], y1, y2, 1);
        events.emplace_back(rects[i][2], y1, y2, -1);
    }
    sort(events.begin(), events.end());
    SegmentTree seg(ys);
    ll ans = 0, prev_x = events[0].x;
    for (auto& e : events) {
        ans = (ans + (e.x - prev_x) % MOD * seg.len[1] % MOD) % MOD;
        seg.update(1, 0, seg.n, e.y1, e.y2, e.type);
        prev_x = e.x;
    }
    cout << ans % MOD << endl;
    return 0;
}
```

**Key Points:**
- Discretize y-coordinates to keep the segment tree small.
- Use a segment tree to maintain the covered length on the y-axis.
- For each event, calculate the area since the last x.
- Output the result modulo 1e9+7.

