```java
import java.util.*;

public class StaircaseWays {
    static int count = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("请输入台阶总数 n：");
        int n = scanner.nextInt();
        scanner.close();

        List<Integer> path = new ArrayList<>();
        System.out.println("所有走法如下：");
        findWays(n, path);

        System.out.println("总共有 " + count + " 种走法。");
    }

    public static void findWays(int n, List<Integer> path) {
        if (n == 0) {
            System.out.println(path);
            count++;
            return;
        }
        if (n >= 1) {
            path.add(1);
            findWays(n - 1, path);
            path.remove(path.size() - 1);
        }
        if (n >= 2) {
            path.add(2);
            findWays(n - 2, path);
            path.remove(path.size() - 1);
        }
    }
}
```

