        for (List<Integer> way : allWays) {
            System.out.println(way);
        }
    }

    // 回溯递归方法
    private static void findWays(int n, List<Integer> current, List<List<Integer>> allWays) {
        if (n == 0) {
            allWays.add(new ArrayList<>(current));
            return;
        }
        if (n < 0) {
            return;
        }
        // 走一步
        current.add(1);
        findWays(n - 1, current, allWays);
        current.remove(current.size() - 1);

        // 走两步
        current.add(2);
        findWays(n - 2, current, allWays);
        current.remove(current.size() - 1);
    }
}
