        for (int i = 1; i < n; i += 2) {
            if (s[i] == '(') {
                open_even++;
                sum_even_open += (i + 1);
            }
        }
        int r = m - open_even; // number of '(' to assign in odd positions

        // Precompute prefix sum of even positions for balance calculation
        vector<int> prefix_even(m + 1, 0);
        for (int k = 1; k <= m; ++k) {
            int idx = 2 * k - 2;
            prefix_even[k] = prefix_even[k - 1] + (s[idx] == '(' ? 1 : -1);
